// Get qualified stocks (from Get Qualified Stocks node)
const qualifiedInput = $('Get Qualified Stocks').all();
// Get already published blogs (from Get Published Blogs node)
const publishedInput = $('Get Published Blogs').all();

if (!qualifiedInput || qualifiedInput.length === 0) {
  return [{ json: { skip: true, message: 'No data from API' } }];
}

// Parse qualified stocks - handle all response shapes
let allStocks = [];
if (Array.isArray(qualifiedInput[0].json)) {
  allStocks = qualifiedInput[0].json;
} else if (qualifiedInput.length > 1 && qualifiedInput[0].json && qualifiedInput[0].json.symbol) {
  allStocks = qualifiedInput.map(s => s.json);
} else if (qualifiedInput[0].json && Array.isArray(qualifiedInput[0].json.stocks)) {
  allStocks = qualifiedInput[0].json.stocks;
} else {
  allStocks = [qualifiedInput[0].json];
}

// Filter: must have score >= 80 or be marked pass, and have a valid symbol
const qualified = allStocks.filter(s => s && s.symbol && (s.score >= 80 || s.isPass === true));
if (qualified.length === 0) {
  return [{ json: { skip: true, message: 'No qualified stocks today' } }];
}

// Parse already-published blogs to find which symbols have recent articles
let publishedSlugs = [];
if (publishedInput && publishedInput.length > 0) {
  const allBlogs = Array.isArray(publishedInput[0].json)
    ? publishedInput[0].json
    : publishedInput.map(b => b.json);
  // Get current month/year to allow re-publishing after 30 days
  const now = new Date();
  const cutoff = new Date(now.getFullYear(), now.getMonth(), 1); // first of current month
  publishedSlugs = allBlogs
    .filter(b => b && b.slug && new Date(b.created_at || b.date || 0) >= cutoff)
    .map(b => b.slug.toLowerCase());
}

// Determine which stocks have NOT been published this month
// A stock is considered "already published" if its symbol appears in any recent slug
const unpublished = qualified.filter(s => {
  const sym = s.symbol.toLowerCase();
  // Check if this symbol appears in any recently published slug
  return !publishedSlugs.some(slug => slug.includes(sym));
});

// If all stocks published this month, reset and pick from all qualified
const pool = unpublished.length > 0 ? unpublished : qualified;

// Shuffle pool using date-seeded deterministic randomness
// This ensures same stock isn't picked twice in a row even across restarts
const today = new Date();
const seed = today.getFullYear() * 10000 + (today.getMonth() + 1) * 100 + today.getDate();
const shuffled = pool.slice().sort(() => {
  const x = Math.sin(seed + pool.indexOf(pool[0])) * 10000;
  return x - Math.floor(x) - 0.5;
});
// Fisher-Yates shuffle with seeded index
for (let i = shuffled.length - 1; i > 0; i--) {
  const j = Math.floor(((Math.sin(seed + i) * 10000) - Math.floor(Math.sin(seed + i) * 10000)) * (i + 1));
  [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
}

// Pick the FIRST stock from the shuffled pool
const picked = shuffled[0];

console.log(`[Blog Picker] Pool: ${pool.length} unpublished stocks. Picked: ${picked.symbol} (score: ${picked.score})`);
console.log(`[Blog Picker] Published this month: ${publishedSlugs.join(', ') || 'none'}`);

return [{ json: picked }];

// Merge qualified stock meta + detailed stock data into one context object
const stockData = $input.first().json;
const pickedStock = $('Pick Next Stock').first().json;

// Merge both objects (stockData takes priority for price/fundamentals)
const merged = { ...pickedStock, ...stockData };

// Ensure key fields exist with safe fallbacks
merged.symbol = merged.symbol || pickedStock.symbol || 'UNKNOWN';
merged.sector = merged.sector || 'Diversified';
merged.price = merged.price || merged.currentPrice || 0;
merged.marketCap = merged.marketCap || 0;
merged.peRatio = merged.peRatio || merged.trailingPE || 'N/A';
merged.returnOnEquity = merged.returnOnEquity !== undefined ? (merged.returnOnEquity * 100).toFixed(1) : 'N/A';
merged.roce = merged.roce || merged.returnOnCapitalEmployed || 'N/A';
merged.debtToEquity = merged.debtToEquity !== undefined ? merged.debtToEquity : 'N/A';
merged.beta = merged.beta || 'N/A';
merged.fiftyTwoWeekHigh = merged.fiftyTwoWeekHigh || merged.yearHigh || 'N/A';
merged.fiftyTwoWeekLow = merged.fiftyTwoWeekLow || merged.yearLow || 'N/A';
merged.upside = merged.upside || 'N/A';
merged.auditScore = merged.score || merged.auditScore || 0;
merged.isQualified = merged.isPass || merged.isQualified || false;

// Stringify complex objects for the prompt
merged.profitabilityQualityText = JSON.stringify(merged.profitabilityQuality || {});
merged.balanceSheetSafetyText = JSON.stringify(merged.balanceSheetSafety || {});
merged.growthQualityText = JSON.stringify(merged.growthQuality || {});
merged.strategiesText = (merged.strategies || []).map(s => (s && (s.name || s))).filter(Boolean).join(', ') || 'None active';

return [{ json: merged }];

const input = $input.all();
const rawContent = input[0].json.choices[0].message.content;
let parsed = {};
try {
  const cleanStr = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanStr);
} catch (e) {
  throw new Error('Failed to parse LLM JSON: ' + e.message + '. Content: ' + rawContent.substring(0, 200));
}

// Ensure slug is unique by appending a timestamp suffix if it doesn't have one
if (parsed.slug && !parsed.slug.match(/-[a-z0-9]{4,8}$/)) {
  const suffix = Date.now().toString(36).slice(-4);
  parsed.slug = `${parsed.slug}-${suffix}`;
}

return [{ json: parsed }];

